<style>
.tl-page{--cream:#FAFAF7;--white:#fff;--charcoal:#1A1A1A;--navy:#0D2137;--ice:#E8F1F8;--sky:#3B82C4;--accent:#E85D26;--gold:#C9A84C;--light-gray:#F4F4F0;--mid-gray:#8A8A82;--border:#E2E2DA;--shadow:0 4px 32px rgba(0,0,0,.08);--shadow-lg:0 16px 64px rgba(0,0,0,.14);font-family:'DM Sans',sans-serif;background:var(--cream);color:var(--charcoal);line-height:1.6;overflow:hidden;padding-top:96px}.tl-page *{box-sizing:border-box}.tl-page a{color:inherit}.tl-page img,.tl-page video,.tl-page iframe{max-width:100%}.tl-page section{padding:96px 32px}.tl-page .container{max-width:1280px;margin:0 auto}.tl-page .section-eyebrow{font-size:12px;font-weight:800;letter-spacing:.2em;text-transform:uppercase;color:var(--sky);margin-bottom:12px}.tl-page .section-title{font-family:'Playfair Display',serif;font-size:clamp(32px,4vw,52px);font-weight:900;color:var(--navy);line-height:1.1;letter-spacing:-.02em;margin:0}.tl-page .section-title .italic{font-style:italic;font-weight:400}.tl-page .section-sub{font-size:17px;color:var(--mid-gray);max-width:580px;margin:14px 0 0;line-height:1.7}.tl-page .btn{display:inline-flex;align-items:center;gap:8px;padding:10px 20px;border-radius:10px;font-size:14px;font-weight:700;text-decoration:none;transition:all .25s;cursor:pointer;border:none;font-family:'DM Sans',sans-serif}.tl-page .btn-primary{background:var(--accent);color:white}.tl-page .btn-primary:hover{background:#d14f1e;transform:translateY(-1px);box-shadow:0 8px 24px rgba(232,93,38,.3)}.tl-page .btn-outline{background:transparent;color:var(--navy);border:1.5px solid var(--navy)}.tl-page .btn-outline:hover{background:var(--navy);color:white}
