#accueil{min-height:100vh;display:flex;flex-direction:column;justify-content:center;position:relative;overflow:hidden;padding-top:72px}.hero-slideshow{position:absolute;inset:0;z-index:0}.hero-slide{position:absolute;inset:0;opacity:0;transition:opacity 1.2s ease-in-out;background-size:cover;background-position:center}.hero-slide.active{opacity:1}.hero-slide img,.hero-slide video,.hero-slide iframe{width:100%;height:100%;object-fit:cover;border:0}.hero-overlay{position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,33,55,.65) 0%,rgba(13,33,55,.3) 50%,rgba(13,33,55,.8) 100%);z-index:1}.hero-snow{position:absolute;inset:0;z-index:2;pointer-events:none;overflow:hidden}.snowflake{position:absolute;top:-10px;border-radius:50%;background:rgba(255,255,255,.7);animation:snowfall linear infinite}@keyframes snowfall{to{transform:translateY(110vh) rotate(360deg)}}.hero-content{position:relative;z-index:3;max-width:1280px;margin:0 auto;padding:80px 32px 60px;width:100%}.hero-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.15);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.25);border-radius:100px;padding:6px 16px;color:white;font-size:13px;font-weight:600;margin-bottom:28px}.hero-badge-dot{width:7px;height:7px;background:#4ade80;border-radius:50%;animation:pulse 2s infinite}@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.6;transform:scale(1.3)}}.hero-title{font-family:'Playfair Display',serif;font-size:clamp(44px,7vw,88px);font-weight:900;color:white;line-height:1;letter-spacing:-.02em;max-width:850px;margin:0}.hero-title .accent{color:var(--gold)}.hero-title .italic{font-style:italic;font-weight:400}.hero-sub{font-size:clamp(16px,2.5vw,20px);color:rgba(255,255,255,.84);margin-top:20px;max-width:560px;font-weight:300;line-height:1.6}.hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:40px}.btn-hero{padding:16px 32px!important;font-size:16px!important;border-radius:12px!important}.btn-white{b